"""Lazy public facade for FlowGuard's current package API.

The generated metadata below is the single name-to-owner projection for the
public facade.  Importing :mod:`flowguard` therefore loads only this small
facade; a public symbol loads its owning module on first access.  The eager
facade remains the current source for the small set of aggregate API maps and
is only loaded when one of those aggregates is explicitly requested.
"""

from __future__ import annotations

import base64
import importlib
import json
import zlib
from typing import Any


# Preserve the historical package-import side effect without importing the
# eager public facade.  The adapters are a small, current package boundary
# and their registration is required by the CLI work-context contract.
from .work_context_adapters import (
    register_builtin_work_context_adapters as _register_builtin_work_context_adapters,
)

_register_builtin_work_context_adapters()
del _register_builtin_work_context_adapters


_API_METADATA = json.loads(
    zlib.decompress(
        base64.b64decode(
            ""
        )
    )
)
if _API_METADATA.get("schema_version") != "flowguard.lazy_public_api.v1":
    raise RuntimeError("unsupported FlowGuard lazy public API metadata")

__all__ = list(_API_METADATA["names"])
_LAZY_OWNERS = dict(_API_METADATA["owners"])
_EAGER_OWNER = "flowguard._eager_exports"
_EAGER_PRIVATE_NAMES = frozenset({"_PUBLIC_API_SUPPLEMENT", "PLAN_INTAKE_CLAIM_API"})


def _load_eager_facade() -> Any:
    return importlib.import_module(_EAGER_OWNER)


def __getattr__(name: str) -> Any:
    if name in _LAZY_OWNERS:
        owner = _LAZY_OWNERS[name]
        if owner != _EAGER_OWNER:
            try:
                module = importlib.import_module(owner)
                value = getattr(module, name)
            except AttributeError:
                # A stale generated owner is a blocked projection, not a
                # silently different public value; use the current facade so
                # the existing API error remains precise.
                pass
            else:
                globals()[name] = value
                return value
        facade = _load_eager_facade()
        try:
            value = getattr(facade, name)
        except AttributeError:
            raise AttributeError(f"module {__name__!r} has no attribute {name!r}") from None
        globals()[name] = value
        return value
    if name in _EAGER_PRIVATE_NAMES:
        facade = _load_eager_facade()
        value = getattr(facade, name)
        globals()[name] = value
        return value
    # Preserve the historical package-level compatibility surface for names
    # that were available from the eager facade without being part of its
    # documented __all__ (for example a legacy direct import used by an
    # internal test).  Unknown names still raise the same AttributeError after
    # this exact current facade lookup; only an actual compatibility lookup
    # pays the eager import cost.
    facade = _load_eager_facade()
    try:
        value = getattr(facade, name)
    except AttributeError:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}") from None
    globals()[name] = value
    return value


def __dir__() -> list[str]:
    return sorted(set(globals()) | set(__all__) | set(_EAGER_PRIVATE_NAMES))
